package com.nivor.notification;import com.nivor.common.entity.AuditedEntity;import com.nivor.user.User;import jakarta.persistence.*;
@Entity @Table(name="notifications",indexes=@Index(name="idx_notification_user_read",columnList="user_id,is_read,created_at"))public class Notification extends AuditedEntity{@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@Enumerated(EnumType.STRING)@Column(nullable=false,length=24)private NotificationType type;@Column(nullable=false,length=160)private String title;@Column(nullable=false,length=500)private String message;@Column(name="is_read",nullable=false)private boolean read;@Column(length=32)private String relatedEntityType;private Long relatedEntityId;protected Notification(){}public User getUser(){return user;}public void setUser(User v){user=v;}public NotificationType getType(){return type;}public void setType(NotificationType v){type=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public boolean isRead(){return read;}public void setRead(boolean v){read=v;}public String getRelatedEntityType(){return relatedEntityType;}public void setRelatedEntityType(String v){relatedEntityType=v;}public Long getRelatedEntityId(){return relatedEntityId;}public void setRelatedEntityId(Long v){relatedEntityId=v;}}
